SELECT * FROM (
    SELECT b.`id` AS bid,b.`title`,b.`description`,b.`cover`,b.`isoriginal`,
    b.content,b.`ispublic`,b.`iscomment`,b.`issue`,b.`browsecount`,b.`likes`,
    b.`collection`,b.`typeid`,b.`userid`,b.`tagjson`,b.`isdel`,b.`createtime`,
    b.`updtime`,u.`id` AS uid,u.`username` AS uName,u.`nickname` AS uNickname,
    u.`avatar`,u.`email`,t.id,t.`name`AS tName,t.note,
    IF(l.user_id IS NOT NULL, 1, 0) AS is_liked,
    IF(c.user_id IS NOT NULL, 1, 0) AS is_collection
    FROM t_blog b
    LEFT JOIN sys_user u
    ON b.`userid` = u.`id`
    LEFT JOIN t_type t
    ON t.id = b.typeid
    LEFT JOIN t_blog_like l ON l.blog_id = b.id AND l.user_id = #{uID}
    LEFT JOIN t_blog_collection c ON c.blog_id = b.id AND c.user_id = #{uID}
) T


        and T.`ispublic` = #{ispublic,jdbcType=VARCHAR}


        and T.`isoriginal` = #{isoriginal,jdbcType=VARCHAR}


        and T.`issue` = #{issue,jdbcType=VARCHAR}


        and T.`isdel` = #{isdel,jdbcType=VARCHAR}


        and T.`is_liked` = #{isLiked}


        and T.`userid` = #{authorID}


        and T.`typeid` = #{type,jdbcType=VARCHAR}


        and T.`is_collection` = #{isCollection}


        and T.`title` LIKE CONCAT('%',#{title},'%')


ORDER BY T.`createtime` DESC

SELECT * FROM (
    SELECT
    b.`id` AS bid,b.`title`,b.`description`,b.`cover`,b.`isoriginal`,
    b.content,b.`ispublic`,b.`iscomment`,b.`issue`,b.`browsecount`,b.`likes`,
    b.`collection`,b.`typeid`,b.`userid`,b.`tagjson`,b.`isdel`,b.`createtime`,
    b.`updtime`,u.`id` AS uid,u.`username` AS uName,u.`nickname` AS uNickname,
    u.`avatar`,u.`email`,u.`description`,t.id,t.`name`AS tName,t.note,
    IF(l.user_id IS NOT NULL, 1, 0) AS is_liked,
    IF(c.user_id IS NOT NULL, 1, 0) AS is_collection
    FROM
    t_blog b
    LEFT JOIN sys_user u
    ON b.`userid` = u.`id`
    LEFT JOIN t_type t
    ON t.id = b.typeid
    LEFT JOIN t_blog_like l ON l.blog_id = b.id AND l.user_id = #{uID}
    LEFT JOIN t_blog_collection c ON c.blog_id = b.id AND c.user_id = #{uID}
) T


        and T.`ispublic` = #{ispublic,jdbcType=VARCHAR}


        and T.`isoriginal` = #{isoriginal,jdbcType=VARCHAR}


        and T.`issue` = #{issue,jdbcType=VARCHAR}


        and T.`isdel` = #{isdel,jdbcType=VARCHAR}


        and T.`is_liked` = #{isLiked}


        and T.`is_collection` = #{isCollection}


