        and T.`title` LIKE CONCAT('%',#{title},'%')


ORDER BY b.`createtime` DESC

SELECT b.`id` AS bid,b.`title`,b.`description`,b.`cover`,b.`isoriginal`, b.content,b.`ispublic`,b.`iscomment`,b.`issue`,b.`browsecount`,b.`likes`, b.`collection`,b.`typeid`,b.`userid`,b.`tagjson`,b.`isdel`,b.`createtime`, b.`updtime`,u.`id` AS uid,u.`username` AS uName,u.`nickname` AS uNickname, u.`avatar`,u.`email`,u.`description`,t.id,t.`name`AS tName,t.note, IF(l.user_id IS NOT NULL, 1, 0) AS is_liked FROM t_blog b LEFT JOIN sys_user u ON b.`userid` = u.`id` LEFT JOIN t_type t ON t.id = b.typeid LEFT JOIN t_blog_like l ON l.blog_id = b.id AND l.user_id = #{uID} WHERE issue=1 AND ispublic = 1 AND isdel = 0 AND b.`userid` = #{uID}
and b.`title` LIKE CONCAT('%',#{title},'%')
and b.`typeid` = #{type,jdbcType=VARCHAR}
AND JSON_OVERLAPS(tagjson, JSON_ARRAY(
CAST(#{tag} AS DECIMAL(20,0))
))

