UPDATE t_blog SET title = #{title,jdbcType=VARCHAR},description = #{description},content = #{content},cover = #{cover},
  isoriginal = #{isoriginal},ispublic = #{ispublic},iscomment = #{iscomment},issue = #{issue},typeid = #{typeid},tagjson = #{tagjson},
  updtime = #{updtime}
WHERE id = #{id}
